"""Contracts that common MCP SDKs generate, and the limits that keep validation bounded."""
import pytest

from driftguard.input_contracts import MAX_BRANCHES, supported_input_schema, valid_arguments

# Shape generated by Pydantic v2 / FastMCP for a model with Optional and nested fields.
PYDANTIC = {
    "type": "object",
    "$defs": {
        "Color": {"enum": ["red", "green"], "type": "string", "title": "Color"},
        "Filter": {
            "type": "object",
            "properties": {"color": {"$ref": "#/$defs/Color"},
                           "since": {"type": "string", "format": "date-time"}},
            "required": ["color"],
            "additionalProperties": False,
        },
    },
    "properties": {
        "query": {"type": "string"},
        "limit": {"anyOf": [{"type": "integer", "minimum": 1}, {"type": "null"}], "default": None},
        "filter": {"anyOf": [{"$ref": "#/$defs/Filter"}, {"type": "null"}]},
    },
    "required": ["query"],
}

# Shape generated by zod-to-json-schema (TypeScript SDK).
ZOD = {
    "$schema": "http://json-schema.org/draft-07/schema#",
    "type": "object",
    "definitions": {"Mode": {"type": "string", "enum": ["fast", "full"]}},
    "properties": {
        "url": {"type": "string", "format": "uri"},
        "mode": {"$ref": "#/definitions/Mode", "description": "Scan depth"},
        "tags": {"type": "array", "items": {"oneOf": [{"type": "string"}, {"type": "integer"}]}},
    },
    "required": ["url"],
    "additionalProperties": False,
}


def test_pydantic_optional_and_nested_models_are_validated():
    assert supported_input_schema(PYDANTIC)
    assert valid_arguments(PYDANTIC, {"query": "x"})
    assert valid_arguments(PYDANTIC, {"query": "x", "limit": None, "filter": {"color": "red"}})
    assert valid_arguments(PYDANTIC, {"query": "x", "filter": {"color": "red", "since": "not a date"}})
    assert not valid_arguments(PYDANTIC, {"query": "x", "limit": 0})
    assert not valid_arguments(PYDANTIC, {"query": "x", "filter": {"color": "blue"}})
    assert not valid_arguments(PYDANTIC, {"query": "x", "filter": {"color": "red", "extra": 1}})


def test_zod_definitions_and_branches_are_validated():
    assert supported_input_schema(ZOD)
    assert valid_arguments(ZOD, {"url": "https://a", "mode": "fast", "tags": ["a", 1]})
    assert not valid_arguments(ZOD, {"url": "https://a", "mode": "slow"})
    assert not valid_arguments(ZOD, {"url": "https://a", "tags": [True]})
    assert not valid_arguments(ZOD, {"url": "https://a", "other": 1})


def test_one_of_requires_exactly_one_match_and_not_inverts():
    schema = {"oneOf": [{"type": "integer"}, {"type": "number"}]}
    assert valid_arguments({"type": "object", "properties": {"v": schema}}, {"v": 1.5})
    assert not valid_arguments({"type": "object", "properties": {"v": schema}}, {"v": 1})
    negated = {"type": "object", "properties": {"v": {"not": {"type": "string"}}}}
    assert valid_arguments(negated, {"v": 1})
    assert not valid_arguments(negated, {"v": "s"})


def test_ref_siblings_with_constraints_are_combined():
    schema = {"$defs": {"S": {"type": "string"}},
              "properties": {"v": {"$ref": "#/$defs/S", "maxLength": 2}}}
    assert valid_arguments(schema, {"v": "ab"})
    assert not valid_arguments(schema, {"v": "abc"})
    assert not valid_arguments(schema, {"v": 1})


@pytest.mark.parametrize("schema", [
    {"$ref": "https://example.invalid/remote"},
    {"$ref": "#/$defs/missing", "$defs": {}},
    {"$ref": "#/$defs/a/b", "$defs": {"a": {"b": {}}}},
    {"$ref": "#/$defs/%61", "$defs": {"a": {}}},
    {"$defs": {"Node": {"properties": {"child": {"$ref": "#/$defs/Node"}}}},
     "properties": {"root": {"$ref": "#/$defs/Node"}}},
    {"properties": {"v": {"$defs": {}}}},
    {"properties": {"v": {"type": "string", "pattern": "(a+)+$"}}},
    {"patternProperties": {"x": {}}},
    {"anyOf": []},
    {"oneOf": {"type": "string"}},
    {"if": {}, "then": {}},
    {"properties": {"v": {"format": 1}}},
    {"$schema": 7},
])
def test_unsupported_or_unsafe_contracts_fail_closed(schema):
    assert not supported_input_schema(schema)
    assert not valid_arguments(schema, {})


def test_shared_definitions_cannot_multiply_validation_work():
    # Each level references the next twice: inlining would need 2**30 nodes.
    defs = {f"L{i}": {"anyOf": [{"$ref": f"#/$defs/L{i + 1}"}, {"$ref": f"#/$defs/L{i + 1}"}]}
            for i in range(30)}
    defs["L30"] = {"type": "string"}
    assert not supported_input_schema({"$defs": defs, "properties": {"v": {"$ref": "#/$defs/L0"}}})


def test_branch_count_is_bounded():
    wide = {"properties": {"v": {"anyOf": [{"const": i} for i in range(MAX_BRANCHES + 1)]}}}
    assert not supported_input_schema(wide)
    narrow = {"properties": {"v": {"anyOf": [{"const": i} for i in range(MAX_BRANCHES)]}}}
    assert valid_arguments(narrow, {"v": 3})


def test_property_named_like_a_keyword_is_not_a_keyword():
    schema = {"$schema": "http://json-schema.org/draft-07/schema#",
              "properties": {"prefixItems": {"type": "string"}, "pattern": {"type": "string"}}}
    assert valid_arguments(schema, {"prefixItems": "a", "pattern": "b"})
